/// <reference types="astro/client" />

// -----------------------------------------------------------------------------
// Virtual modules generated by Starlight plugins at Astro build time.
// -----------------------------------------------------------------------------
declare module 'virtual:starlight-blog/configs' {
  const configs: any;
  export default configs;
}
declare module 'virtual:starlight-blog/context' {
  // `trailingSlash` is the only field starlight-blog uses as an index into a
  // strongly-typed Record. Everything else falls through to the index signature.
  const context: {
    trailingSlash: 'always' | 'ignore' | 'never';
    [key: string]: any;
  };
  export default context;
}
declare module 'virtual:starlight-view-modes/context' {
  const context: any;
  export default context;
}
declare module 'virtual:starlight-view-modes/config' {
  const config: any;
  export default config;
}

// -----------------------------------------------------------------------------
// Direct-import stubs (also referenced via tsconfig "paths"). Remove when
// @astrojs/starlight >=0.43 is fleet-wide (enables starlight-view-modes@0.16).
// -----------------------------------------------------------------------------
declare module 'starlight-view-modes' {
  const plugin: (opts?: Record<string, unknown>) => unknown;
  export default plugin;
}
declare module 'starlight-telescope' {
  const plugin: (opts?: Record<string, unknown>) => unknown;
  export default plugin;
}

declare module 'virtual:starlight-changelogs/config' {
  export function setLoaderConfig(config: unknown): void;
}

declare module '*.astro' {
  const component: any;
  export default component;
}
